Here's a simple end-user API for 3D camera animation in TypeScript:

```typescript
interface CameraAnimation {
  id: number;
  name: string;
  duration: number;
  easing: string;
  cameraId: number;
  animationData: any;
}

class CameraAnimationService {
  private cameraAnimations: CameraAnimation[] = [];

  addCameraAnimation(cameraAnimation: CameraAnimation) {
    this.cameraAnimations.push(cameraAnimation);
  }

  getCameraAnimations() {
    return this.cameraAnimations;
  }

  updateCameraAnimation(id: number, updatedAnimation: CameraAnimation) {
    const index = this.cameraAnimations.findIndex((a) => a.id === id);
    if (index !== -1) {
      this.cameraAnimations[index] = updatedAnimation;
    }
  }

  deleteCameraAnimation(id: number) {
    const index = this.cameraAnimations.findIndex((a) => a.id === id);
    if (index !== -1) {
      this.cameraAnimations.splice(index, 1);
    }
  }
}

const cameraAnimationService = new CameraAnimationService();

// Example usage
cameraAnimationService.addCameraAnimation({
  id: 1,
  name: 'Example Animation',
  duration: 5000,
  easing: 'easeInOutQuad',
  cameraId: 1,
  animationData: { /* ... */ },
});

console.log(cameraAnimationService.getCameraAnimations());

const updatedAnimation = {
  id: 1,
  name: 'Updated Animation',
  duration: 6000,
  easing: 'easeInOutCubic',
  cameraId: 1,
  animationData: { /* ... */ },
};

cameraAnimationService.updateCameraAnimation(1, updatedAnimation);

console.log(cameraAnimationService.getCameraAnimations());

cameraAnimationService.deleteCameraAnimation(1);

console.log(cameraAnimationService.getCameraAnimations());
```

