            AudioInputStream audioStream1 = AudioSystem.getAudioInputStream(audio1);
            AudioInputStream audioStream2 = AudioSystem.getAudioInputStream(audio2);
            AudioInputStream audioStream3 = AudioSystem.getAudioInputStream(audio3);

            Clip clip1 = AudioSystem.getClip();
            clip1.open(audioStream1);

            Clip clip2 = AudioSystem.getClip();
            clip2.open(audioStream2);

            Clip clip3 = AudioSystem.getClip();
            clip3.open(audioStream3);

            // Mix the audio streams
            float[] buffer = new float[clip1.getFormat().getChannels() * clip1.getFormat().getSampleSizeInBits() / 8];
            int read = 0;
            while (read != -1) {
                read = clip1.read(buffer, 0, buffer.length);
                if (read != -1) {
                    clip2.write(buffer, 0, read);
                    clip3.write(buffer, 0, read);
                }
            }

            // Play the mixed audio stream
            Clip mixedClip = AudioSystem.getClip();
            mixedClip.open(AudioSystem.getAudioInputStream(new ByteArrayInputStream(buffer)));
            mixedClip.start();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
