int main() {
    double purchase_price = 1000;
    double residual_value = 200;
    double total_amount_of_refund = purchase_price - residual_value;
    double percentage_of_purchase_price_refunded = (total_amount_of_refund / purchase_price) * 100;

    std::cout << "The percentage of the purchase price that is refunded is " << percentage_of_purchase_price_refunded << "%." << std::endl;

