#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int n, a, b;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> a >> b)) {
        cerr << "Invalid input. Please enter two integers." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    if (n < 1) {
        cerr << "Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    int sequence[n];
    sequence[0] = a;
    sequence[1] = b;

    for (int i = 2; i < n; i++) {
        sequence[i] = fibonacci(i, b, a + b);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < n; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

Here's a C++ program that uses a recursive function to generate the Fibonacci sequence:

```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;
    int sequenceLength;

    cout << "Enter the first two numbers in the Fibonacci sequence: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (num1 < 0 || num2 < 0) {
        cout << "Error: Both numbers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the length of the Fibonacci sequence: ";
    cin >> sequenceLength;

    if (sequenceLength < 1) {
        cout << "Error: The length of the sequence must be at least 1." << endl;
        return 1;
    }

    int result = fibonacci(sequenceLength, num1, num2);

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequenceLength; i++) {
        cout << result << ", ";
        result = fibonacci(sequenceLength - i - 1, num2, result);
    }
    cout << endl;

    return 0;
}
