func replaceHomophones(in passage: String) -> String {
    let homophones = [
        "their": "there",
        "they're": "there",
        "too": "to"
    ]

    for (oldWord, newWord) in homophones {
        passage = passage.replacingOccurrences(of: oldWord, with: newWord)
    }

    return passage
}

