```prisma
datasource db {
  provider = "mongodb"
  url      = env("MONGODB_URI")
}

generator client {
  provider = "prisma-client-js"
  output   = "../client/prisma"
  previewFeatures = ["migrations"]
}

model User {
  id        Int     @id @default(autoincrement())
  email     String  @unique
  password  String
}

model Todo {
  id       Int     @id @default(autoincrement())
  title    String
  content  String
  user     User   @relation(fields: [userId], references: [id])
  userId   Int
}
```

