import requests
from bs4 import BeautifulSoup
import os

def download_photo(url):
    response = requests.get(url)
    if response.status_code == 200:
        with open('photo.jpg', 'wb') as f:
            f.write(response.content)
        return True
    else:
        return False

def download_album_photos(album_link):
