    photos = soup.find_all('div', class_='gallery-photo')
    for photo in photos:
        url = photo.find('img').get('src')
        if download_photo(url):
            print(f"Downloaded {url}")
        else:
            print(f"Error downloading {url}")

if __name__ == '__main__':
