Here's a function that maps the values from 0..1 to 0..1 in a way that starts smoothy, has a linear range in the middle, and then stops smoothly again:

```javascript
function smoothLinearMap(x) {
  if (x < 0.25) {
    return x * 4;
  } else if (x < 0.5) {
    return 2 - (x - 0.5) * 2;
  } else if (x < 0.75) {
    return x - 0.5;
  } else {
    return 1 - (x - 0.75) * 2;
  }
}
```

This function first maps the input value `x` to the range [0, 1] by multiplying it by 4 if `x` is less than 0.25, subtracting twice the difference between `x` and 0.5 if `x` is between 0.25 and 0.5, returning the value of `x` minus 0.5 if `x` is between 0.5 and 0.75, and finally subtracting twice the difference between `x` and 0.75 if `x` is greater than 0.75. This results in a smooth transition from the starting point to the linear range, followed by a smooth transition to the ending point.

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getObjectEntriesByKey(obj, key) {
  const entries = Object.entries(obj);
  const filteredEntries = entries.filter(([key, value]) => value === key);
  return filteredEntries;
}
```

You can use this function like this:

```javascript
const obj = {
  'a.b': 'c',
  'd.e': 'f',
  'g.h': 'i'
};

const key = 'a.b';

const entries = getObjectEntriesByKey(obj, key);
console.log(entries); // Output: [['a.b', 'c']]
```

```javascript
function getOptionValues(dotNotationString, object) {
  const keys = dotNotationString.split('.');
  let currentObject = object;

  for (const key of keys) {
    if (!currentObject[key]) {
      return [];
    }
    currentObject = currentObject[key];
  }

  return currentObject;
}
```

```javascript
function getOptionEntries(dotNotatedString, key) {
  const options = dotNotatedString.split(".");
  const result = [];

  for (const option of options) {
    if (option === key) {
      result.push(options.slice(0, options.indexOf(key) + 1).join("."));
    }
  }

  return result;
}
```

```javascript
function getOptionValues(dotNotationString, options) {
  const keys = dotNotationString.split(".");
  const values = [];

  options.forEach((option) => {
    let currentValue = option;

    for (const key of keys) {
      currentValue = currentValue[key];
    }

    if (currentValue === dotNotationString) {
      values.push(option);
    }
  });

  return values;
}
```

Usage:

```javascript
const dotNotationString = "a.b.c";
const options = [
  { a: { b: { c: "apple" } }, d: "orange" },
  { a: { b: { c: "banana" } }, e: "pear" },
  { f: "grape", g: "strawberry" }
];

const result = getOptionValues(dotNotationString, options);
console.log(result); // Output: [{ a: { b: { c: "apple" } }, d: "orange" }]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getEntriesByKey(obj, key) {
  const entries = [];
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'object') {
      entries.push(...getEntriesByKey(value, key));
    } else if (value === key) {
      entries.push({ key, value });
    }
  }
  return entries;
}

const obj = {
  a: { b: 1, c: 2 },
  d: { e: 3, f: 4 },
  g: 5,
};

const key = 'b';

const result = getEntriesByKey(obj, key);
console.log(result); // Output: [{ key: 'a.b', value: 1 }]
```

