Here's a simple Go program that parses a struct in a Go source file and generates an AVRO schema for it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
)

type StructDefinition struct {
	Name      string `json:"name"`
	Fields   []Field `json:"fields"`
}

type Field struct {
	Name  string `json:"name"`
	Type  string `json:"type"`
	Schema *avro.Schema `json:"schema,omitempty"`
}

func parseStruct(sourceFile string, structName string) (*StructDefinition, error) {
	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		return nil, err
	}

	re := regexp.MustCompile(`struct\s+(\w+)\s*{`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		return nil, fmt.Errorf("invalid struct definition")
	}

	name := matches[1]
	fields := make([]Field, 0)

	// Parse fields
	start := strings.Index(string(content), "{\n") + 3
	end := strings.LastIndex(string(content), "}")
	fieldContent := string(content)[start:end]
	fieldsContent := strings.Split(fieldContent, "\n")

	for _, fieldContent := range fieldsContent {
		if len(fieldContent) == 0 {
			continue
		}

		parts := strings.SplitN(fieldContent, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid field definition")
		}

