                  "type": "record",
                  "name": "%s",
                  "fields": [
                `, structName)

				for _, line := range lines {
					if strings.HasPrefix(line, "    ") {
						parts := strings.SplitN(line, " ", 3)
						if len(parts) == 3 {
							fieldType := parts[1]
							fieldName := parts[2]

							schema += fmt.Sprintf(`{
                                  "type": "%s",
                                  "name": "%s"
                                },`, fieldType, fieldName)
						}
					}
				}

				schema += `]
              }`)

				err = ioutil.WriteFile("struct.avsc", []byte(schema), 0644)
				if err != nil {
					fmt.Println("Error writing file:", err)
					return
				}

				fmt.Printf("Generated AVSC file: struct.avsc\n")
				return

