```python
def is_prime(n: int) -> bool:
    """Checks if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_maximum(numbers: list[int]) -> int:
    """Finds the maximum value in a list of numbers."""
    max_value = numbers[0]
    for number in numbers:
        if number > max_value:
            max_value = number
    return max_value

def calculate_area(shape: str, dimensions: tuple) -> float:
    """Calculates the area of a shape based on its dimensions."""
    if shape == "rectangle":
        return dimensions[0] * dimensions[1]
    elif shape == "circle":
        return dimensions[0] ** 2 * 3.14
    else:
        raise ValueError("Invalid shape")
```

```python
def greet(name: str) -> None:
    """Prints a greeting message"""
    print(f"Hello, {name}!")

def calculate_area(shape: str, length: float, width: float) -> float:
    """Calculates the area of a shape"""
    if shape == "rectangle":
        return length * width
    elif shape == "circle":
        return 3.14 * (length / 2)**2
    else:
        return NotImplementedError("Shape not recognized.")

def check_age(age: int) -> bool:
    """Checks if a person is old enough to vote"""
    return age >= 18

def main():
    name = input("Enter your name: ")
    greet(name)

    shape = input("Enter the shape: ")
    length = float(input("Enter the length: "))
    width = float(input("Enter the width: "))
    area = calculate_area(shape, length, width)
    print(f"The area of the {shape} is {area}.")

    age = int(input("Enter your age: "))
    if check_age(age):
        print("You are old enough to vote.")
    else:
        print("You are not old enough to vote.")

if __name__ == "__main__":
    main()
```

