Here's the C code to convert `argv` (command-line arguments) to a `char*` string:

```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    char *arg_str = malloc(argc * sizeof(char*));
    if (arg_str == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < argc; i++) {
        strcat(arg_str, argv[i]);
        if (i != argc - 1) {
            strcat(arg_str, " ");
        }
    }

    printf("Argument string: %s\n", arg_str);

    free(arg_str);
    return 0;
}
```

