@Controller('api')
export class AppController {
  constructor(private readonly envDecorator: EnvDecorator) {}

  @Get()
  async getHello(): Promise<string> {
    if (await this.envDecorator.canActivate(this)) {
      return 'Hello World!';
    } else {
      return 'Hello World from the other environment';
    }
  }
}
```

