```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IsDevMode = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'development') {
      return true;
    }

    return false;
  },
);
```
You can use this decorator in your controllers like this:
```typescript
@IsDevMode()
async myControllerMethod(req, res) {
  // Your code here
}
```
In this example, `myControllerMethod` will only be called if the `NODE_ENV` variable is set to "development". Otherwise, it will return `false`.

