import { Injectable, CanActivate } from '@nestjs/common';

@Injectable()
export class EnvironmentGuard implements CanActivate {
  canActivate(context: any): boolean {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    } else {
      return false;
    }
  }
}
```

Here's a simple decorator for your Nest.js middleware that checks the `NODE_ENV` variable and calls `next()` if it's set to `true`, otherwise returns `false`.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvMiddleware implements CanActivate {
  canActivate(context: ExecutionContext) {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    }

    return false;
  }
}
```

You can use this middleware in your routes like this:

```typescript
import { Controller, Get } from '@nestjs/common';
import { EnvMiddleware } from './env.middleware';

@Controller()
export class MyController {
  constructor(private readonly envMiddleware: EnvMiddleware) {}

  @Get()
  @UseMiddleware(this.envMiddleware)
  getHello(): string {
    return 'Hello World!';
  }
}
```

This way, when the `GET /` endpoint is called, the `EnvMiddleware` will be executed first. If `NODE_ENV` is set to `true`, the request will proceed to the `getHello` method. Otherwise, the request will be stopped, and a `false` value will be returned.

Here's a decorator for Nest.js middleware that checks the NODE_ENV variable and returns `false` if it's not equal to 'true'. If NODE_ENV is equal to 'true', it calls the `next()` function.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = request.nodeEnv;

    if (nodeEnv === 'true') {
      return true;
    }

    return false;
  }
}
```

To use this decorator, you can apply it to your middleware functions like this:

```typescript
import { MiddlewareFunction, NestMiddleware } from '@nestjs/common';
import { EnvGuard } from './env-guard';

@NestMiddleware()
export class MyMiddleware implements MiddlewareFunction {
  constructor(private readonly envGuard: EnvGuard) {}

  async use(req: Request, res: Response, next: NextFunction) {
    if (await this.envGuard.canActivate(new ExecutionContext(req, res, next))) {
      next();
    } else {
      res.status(403).json({ error: 'Forbidden' });
    }
  }
}
```

