To create a simple toast notification using React Context, follow these steps:

1. Create a ToastContext component:

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  toastMessage: null,
};

const toastReducer = (state, action) => {
  switch (action.type) {
    case 'show-toast':
      return { ...state, toastMessage: action.payload };
    case 'hide-toast':
      return { ...state, toastMessage: null };
    default:
      return state;
  }
};

export const ToastContext = createContext();

export function ToastProvider(props) {
  const [state, dispatch] = useReducer(toastReducer, initialState);

  const showToast = (message) => {
    dispatch({ type: 'show-toast', payload: message });
  };

  const hideToast = () => {
    dispatch({ type: 'hide-toast' });
  };

  return (
    <ToastContext.Provider value={{ showToast, hideToast, state }}>
      {props.children}
    </ToastContext.Provider>
  );
}
```

2. Create a Toast component to display the toast notification:

```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { toastMessage, showToast, hideToast } = React.useContext(ToastContext);

  if (!toastMessage) {
    return null;
  }

  return (
    <div className="toast">
      {toastMessage}
      <button onClick={hideToast}>Close</button>
    </div>
  );
}

export default Toast;
```

