        <div class="prime-number" data-prime="13">13</div>
        <div class="prime-number" data-prime="19">19</div>
    </div>
    <script>
        const primeNumbers = document.querySelectorAll('.prime-number');
        let product = 1;

        primeNumbers.forEach(number => {
            number.addEventListener('click', () => {
                number.classList.toggle('active');

                if (number.classList.contains('active')) {
                    product *= parseInt(number.dataset.prime);
                } else {
                    product /= parseInt(number.dataset.prime);
                }

                console.log(`Product: ${product}`);
            });
        });
    </script>
</body>
