const primeNumbers = [3, 7, 13, 19];
const product = primeNumbers.reduce((a, b) => a * b);

function displayPrimeNumbers() {
    const primeNumbersList = document.getElementById('primeNumbers');
    primeNumbersList.innerHTML = '';

    primeNumbers.forEach(number => {
        const listItem = document.createElement('li');
        listItem.textContent = number;
        primeNumbersList.appendChild(listItem);
    });
}

displayPrimeNumbers();
document.getElementById('product').textContent = `Product: ${product}`;
