            num //= 10
        return " ".join(reversed(words))

# Example usage
print(english_number_representation(1234567890))  # Output: one hundred twenty-three million four hundred fifty-six thousand seven hundred eighty-nine
print(scientific_notation_representation(1e6))     # Output: one million
print(language_specific_representation(123, "fr"))   #

