import gspread

def parse_dict(sheet_key, sheet_name, row_number):
    gc_client = gspread.service_account()
    sheet = gc_client.open_by_key(sheet_key).worksheet(sheet_name)
    data = {}
    for i, row in enumerate(sheet.get_all_rows()):
        if i == row_number - 1:
            for j, cell in enumerate(row.get_all_cells()):
                data[cell.value] = row[j].value
    return data
