import { useCombobox } from 'downshift';
import axios from 'axios';

interface Email {
  email: string;
}

const EmailsInput = () => {
  const [emails, setEmails] = React.useState<Email[]>([]);
  const [inputValue, setInputValue] = React.useState('');

  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: emails,
    itemToString: (item) => item.email,
    selectedItem: null,
  });

  const handleSearch = async (prefix: string) => {
    try {
      const response = await axios.get(`https://api.example.com/emails`, {
        params: { prefix },
      });

      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
    handleSearch(event.target.value);
  };

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} value={inputValue} onChange={handleInputChange} />
      <ul {...getMenuProps()}>
        {isOpen &&
          emails.map((email) => (
            <li key={email.email} {...getMenuItemProps(email)}>
              {email.email}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailsInput;
```

