  const [emails, setEmails] = useState([]);

  const searchEmails = async (prefix: string) => {
    // Implement your email search logic here
    // For now, let's just simulate some data
    const simulatedEmails = [
      { id: 1, email: 'example1@email.com' },
      { id: 2, email: 'example2@email.com' },
      { id: 3, email: 'example3@email.com' },
    ];

    setEmails(simulatedEmails.filter((e) => e.email.startsWith(prefix)));
  };

  const { isOpen, selectedItem, getMenuProps, getComboboxProps, getInputProps } = useCombobox({
    items: emails,
    getItemToString: (item) => item.email,
    onSelect: (selectedItem) => {
      console.log(`Selected item: ${selectedItem}`);
    },
  });

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value);
    searchEmails(event.target.value);
  };

  return (
    <div>
      <input
        {...getInputProps({
          placeholder: 'Enter email',
          value: searchTerm,
          onChange: handleInputChange,
        })}
      />
