        {isOpen ? (
          <ul>
            {emails.map((email) => (
              <li key={email.id} {...getComboboxProps({ selected: email })}>
                {email.email}
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </div>
  );
};

export default EmailInputField;
