To achieve this task, you'll need to install the Accord.NET library first. Then, follow these steps:

1. Install the Accord.NET library by running the following command in the Package Manager Console:

```
Install-Package Accord.NET
```

2. Create a C# console application and add the following code:

```csharp
using System;
using System.IO;
using System.Linq;
using System.Text;
using Accord.MachineLearning;
using Accord.MachineLearning.Classification;
using Accord.MachineLearning.FeatureExtraction;
using Accord.MachineLearning.Metrics;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the dataset
            string datasetPath = @"path\to\your\dataset.txt";
            var dataset = LoadDataset(datasetPath);

            // Preprocess the dataset
            var vectorizer = new CountVectorizer();
            var preprocessedDataset = vectorizer.Transform(dataset);

            // Train the Naive Bayes classifier
            var naiveBayes = new NaiveBayesClassifier();
            naiveBayes.Train(preprocessedDataset);

            // Classify a new sentence
            string newSentence = "The sports game was exciting.";
            var newObservation = vectorizer.Transform(newSentence);
            var prediction = naiveBayes.Predict(newObservation);

            // Print the result
            Console.WriteLine($"Predicted label: {prediction}");
        }

        static Dataset LoadDataset(string path)
        {
            var lines = File.ReadAllLines(path);
            var dataset = new Dataset();

            foreach (var line in lines)
            {
                var parts = line.Split('\t');
                var label = parts[0];
                var sentence = parts[1];
                dataset.Add(label, sentence);
            }

            return dataset;
        }
    }
}
```

