public class CarbonCycle {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the initial forest area (in hectares): ");
        double initialForestArea = scanner.nextDouble();
        System.out.print("Enter the rate of deforestation (in percentage per year): ");
        double deforestationRate = scanner.nextDouble() / 100;
        System.out.print("Enter the amount of carbon stored in forests (in tonnes per hectare): ");
