Here's a simple TypeScript program that generates a bar chart from a user-inputted dataset:
```typescript
// BarChart.tsx
import React, { useState } from 'react';
import { Bar } from 'react-chartjs-2';

interface DataProps {
  labels: string[];
  datasets: [{ label: string; data: number[] }];
}

const BarChart: React.FC<DataProps> = ({ labels, datasets }) => {
  const [data, setData] = useState({
    labels,
    datasets,
  });

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = event.target;
    if (name === 'labels') {
      setData({ ...data, labels: value.split(',') });
    } else if (name === 'datasets') {
      setData({ ...data, datasets: JSON.parse(value) });
    }
  };

  return (
    <div>
      <h2>Bar Chart</h2>
      <form onChange={handleInputChange}>
        <label htmlFor="labels">Labels:</label>
        <input type="text" id="labels" name="labels" />
        <label htmlFor="datasets">Datasets:</label>
        <input type="text" id="datasets" name="datasets" />
      </form>
      <Bar data={data} options={{ maintainAspectRatio: false }} />
    </div>
  );
};

export default BarChart;
```
