const data = [10, 20, 30, 40, 50];

function generateBarChart(data: number[]): void {
  const canvas = document.createElement('canvas');
  canvas.width = 400;
  canvas.height = 200;

  const ctx = canvas.getContext('2d');

  // Set the background color
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Set the bar color
  ctx.fillStyle = 'blue';

  // Calculate the bar width and height
  const barWidth = canvas.width / data.length;
  const barHeight = data.reduce((a, b) => Math.max(a, b), 0);

  // Draw the bars
  for (let i = 0; i < data.length; i++) {
    const x = i * barWidth;
    const y = canvas.height - barHeight * data[i] / barHeight;
    ctx.fillRect(x, y, barWidth, barHeight * data[i] / barHeight);
  }

  // Add a label to the chart
  ctx.fillStyle = 'black';
  ctx.font = '16px Arial';
  ctx.textAlign = 'center';
