Here's a simple React utility to remove widows. This utility will check if a text node has a width less than its parent container and adjust the font size accordingly.

```javascript
import React, { useEffect, useState } from 'react';

const RemoveWidows = ({ children }) => {
  const [fontSize, setFontSize] = useState(16);

  useEffect(() => {
    const adjustFontSize = () => {
      const textNode = document.querySelector('.text-node');
      const parentContainerWidth = textNode.offsetParent.offsetWidth;
      const textNodeWidth = textNode.offsetWidth;

      if (textNodeWidth < parentContainerWidth) {
        setFontSize((prevFontSize) => prevFontSize - 2);
      }
    };

    adjustFontSize();
  }, []);

  return (
    <div className="text-node">
      {children}
      <style jsx>{`
        .text-node {
          font-size: ${fontSize}px;
        }
      `}</style>
    </div>
  );
};

export default RemoveWidows;
```

