```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.redis = new Redis({
      host: 'localhost',
      port: 6379,
      family: 4,
    });

    this.redis.on('error', (err) => {
      console.error('Redis error:', err);
    });
  }

  isAlive() {
    return this.redis.ping().then(() => true).catch(() => false);
  }

  async get(key) {
    try {
      return await this.redis.get(key);
    } catch (err) {
      console.error('Error getting from Redis:', err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.redis.setex(key, duration, value);
    } catch (err) {
      console.error('Error setting in Redis:', err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.redis.del(key);
    } catch (err) {
      console.error('Error deleting from Redis:', err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

